object Solution {
  def maximumBeauty(flowers: Array[Int], newFlowers: Int, target: Int, full: Int, partial: Int): Long = {
    val n = flowers.length
    val sorted = flowers.sorted

    // Count how many gardens are already complete (>= target)
    var completeCount = 0
    while (completeCount < n && sorted(n - 1 - completeCount) >= target) completeCount += 1

    // If all gardens are complete, return full * n
    if (completeCount == n) return full.toLong * n

    // We only care about gardens with flowers < target, since >= target are complete
    // We'll consider the last completeCount gardens as complete, and the rest as incomplete
    val incompleteCount = n - completeCount
    val incomplete = sorted.take(incompleteCount)

    // Prefix sums of incomplete gardens for quick cost calculation
    val prefix = new Array[Long](incompleteCount + 1)
    for (i <- 0 until incompleteCount) {
      prefix(i + 1) = prefix(i) + incomplete(i)
    }

    // Helper function: given a minimum flower count 'minFlower' for incomplete gardens,
    // calculate how many flowers needed to raise all incomplete gardens below minFlower up to minFlower
    def flowersNeeded(minFlower: Int): Long = {
      // Find how many gardens have flowers < minFlower using binary search
      val idx = java.util.Arrays.binarySearch(incomplete, 0, incompleteCount, minFlower)
      val pos = if (idx < 0) -idx - 1 else idx
      // pos is the count of gardens with flowers < minFlower
      val need = minFlower.toLong * pos - prefix(pos)
      need
    }

    var res = 0L

    // Try all possible numbers of complete gardens from completeCount to n
    // For each, calculate how many flowers needed to make those complete,
    // then use remaining flowers to maximize the minimum incomplete garden
    // If we make i gardens complete, they are the top i gardens in sorted order
    // We can plant flowers to make incompleteCount - i gardens incomplete with min flower count
    // The incomplete gardens are the first incompleteCount - i gardens in incomplete array

    // We will iterate i from completeCount to n (number of complete gardens)
    // For i > completeCount, we need to plant flowers to make some incomplete gardens complete

    // Precompute suffix sums of flowers for incomplete gardens to quickly calculate cost to make some complete
    val incompleteRev = incomplete.reverse
    val suffix = new Array[Long](incompleteCount + 1)
    for (i <- 0 until incompleteCount) {
      suffix(i + 1) = suffix(i) + incompleteRev(i)
    }

    // flowers needed to make last k incomplete gardens complete (>= target)
    def flowersToCompleteLastK(k: Int): Long = {
      // last k gardens in incompleteRev are the smallest k gardens from the end
      // For each garden, need (target - flowers[i]) flowers
      val sumFlowers = suffix(k)
      val need = target.toLong * k - sumFlowers
      need
    }

    // Binary search to find max minFlower for incomplete gardens given flowers left
    def maxMinFlower(flowersLeft: Long, incompleteLen: Int): Int = {
      if (incompleteLen == 0) return 0
      var low = incomplete(0)
      var high = target - 1
      var ans = low
      while (low <= high) {
        val mid = (low + high) >>> 1
        val need = flowersNeeded(mid)
        if (need <= flowersLeft) {
          ans = mid
          low = mid + 1
        } else {
          high = mid - 1
        }
      }
      ans
    }

    // Iterate over how many gardens to make complete (from completeCount to n)
    // i is number of complete gardens after planting
    for (i <- completeCount to n) {
      val completeNeeded = i - completeCount
      if (completeNeeded > incompleteCount) {
        // Can't make more complete than total gardens
        // skip
      } else {
        val costToComplete = flowersToCompleteLastK(completeNeeded)
        if (costToComplete <= newFlowers) {
          val flowersLeft = newFlowers - costToComplete
          val incompleteLen = incompleteCount - completeNeeded
          val minFlower = maxMinFlower(flowersLeft, incompleteLen)
          val totalBeauty = full.toLong * i + partial.toLong * minFlower
          if (totalBeauty > res) res = totalBeauty
        }
      }
    }

    res
  }
}

